<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('media');$base='/admin/media.php';
function cmsSyncMediaIndex(PDO $pdo): void {
    $root=realpath(__DIR__.'/../../uploads');if(!$root)return;
    $ins=$pdo->prepare('INSERT IGNORE INTO media_items(file_path,original_name,mime_type,file_size,is_public) VALUES(:p,:n,:m,:s,0)');
    $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));
    foreach($it as $f){if(!$f->isFile()||$f->isLink())continue;$real=$f->getRealPath();if(!$real||!str_starts_with($real,$root.DIRECTORY_SEPARATOR))continue;$rel=str_replace(DIRECTORY_SEPARATOR,'/',substr($real,strlen($root)+1));if($rel==='.htaccess')continue;$mime=function_exists('mime_content_type')?(string)@mime_content_type($real):'';$ins->execute([':p'=>'/uploads/'.$rel,':n'=>basename($real),':m'=>$mime,':s'=>$f->getSize()]);}
}
function cmsMediaReferenced(PDO $pdo,string $path): bool { $checks=[['partners','logo_path'],['gallery_items','image_path'],['reels','media_path'],['reels','poster_path'],['catalog_brands','logo_path'],['catalog_products','image_path']];foreach($checks as [$t,$c]){try{$s=$pdo->prepare("SELECT COUNT(*) FROM `$t` WHERE `$c`=:p");$s->execute([':p'=>$path]);if((int)$s->fetchColumn()>0)return true;}catch(Throwable $e){}}return false; }
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$a=cmsStr($_POST['action']??'upload',20);if($a==='toggle_public'){ $id=cmsInt($_POST['id']??0);$pdo->prepare('UPDATE media_items SET is_public=1-is_public WHERE id=:id')->execute([':id'=>$id]);cmsAudit('media.public.toggle','media_items',(string)$id);cmsAdminRedirect($base,'تم تحديث حالة النشر.'); }if($a==='delete'){ $id=cmsInt($_POST['id']??0);$s=$pdo->prepare('SELECT file_path FROM media_items WHERE id=:id');$s->execute([':id'=>$id]);$p=(string)($s->fetchColumn()?:'');if($p===''||cmsMediaReferenced($pdo,$p))cmsAdminRedirect($base,'الملف مستخدم ولا يمكن حذفه.');$pdo->prepare('DELETE FROM media_items WHERE id=:id')->execute([':id'=>$id]);cmsDeleteLocalUpload($p);cmsAudit('media.delete','media_items',(string)$id);cmsAdminRedirect($base,'تم حذف الملف.'); }
$path=cmsUploadFile('file','media',['jpg','jpeg','png','webp','gif','pdf','mp4','webm'],50*1024*1024);if(!$path)cmsAdminRedirect($base,'اختر ملفًا.');$full=__DIR__.'/../..'.$path;$mime=function_exists('mime_content_type')?(string)@mime_content_type($full):'';$size=is_file($full)?filesize($full):0;$q=$pdo->prepare('INSERT INTO media_items(file_path,original_name,mime_type,file_size,title_ar,title_en,alt_ar,alt_en,is_public) VALUES(:p,:n,:m,:s,:ta,:te,:aa,:ae,:pub)');$q->execute([':p'=>$path,':n'=>cmsSafeFilename((string)($_FILES['file']['name']??'file')),':m'=>$mime,':s'=>(int)$size,':ta'=>cmsStr($_POST['title_ar']??'',255)?:null,':te'=>cmsStr($_POST['title_en']??'',255)?:null,':aa'=>cmsStr($_POST['alt_ar']??'',255)?:null,':ae'=>cmsStr($_POST['alt_en']??'',255)?:null,':pub'=>cmsBool($_POST['is_public']??0)]);cmsAudit('media.upload','media_items',$path);cmsAdminRedirect($base,'تم رفع الملف.');}
cmsSyncMediaIndex($pdo);$rows=$pdo->query('SELECT * FROM media_items ORDER BY id DESC')->fetchAll();cmsAdminHead('مكتبة الوسائط');cmsAdminSidebar('media');cmsAdminTopbar('مكتبة الوسائط');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><section class="card"><h2>رفع ملف</h2><form method="post" enctype="multipart/form-data"><?=cmsCsrfField()?><div class="form-grid"><label class="field"><span>الملف</span><input type="file" name="file" required></label><label class="field"><span>العنوان AR</span><input name="title_ar"></label><label class="field"><span>Title EN</span><input name="title_en"></label><label class="field"><span>Alt AR</span><input name="alt_ar"></label><label class="field"><span>Alt EN</span><input name="alt_en"></label><label class="module-row"><span>Public API</span><input class="check" type="checkbox" name="is_public" value="1" checked></label></div><button class="btn primary" style="margin-top:16px">رفع</button></form></section><section class="card" style="margin-top:18px"><h2>الملفات</h2><div class="table-wrap"><table class="table"><thead><tr><th>معاينة</th><th>المسار</th><th>الحجم</th><th>Public</th><th>مستخدم</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):$used=cmsMediaReferenced($pdo,$r['file_path']);?><tr><td><?php if(str_starts_with((string)$r['mime_type'],'image/')):?><img class="thumb" src="<?=cmsE($r['file_path'])?>" alt=""><?php else:?><span class="pill">FILE</span><?php endif;?></td><td><code><?=cmsE($r['file_path'])?></code><div class="muted"><?=cmsE($r['original_name'])?></div></td><td><?=number_format(((int)$r['file_size'])/1024,1)?> KB</td><td><span class="pill <?=$r['is_public']?'ok':'bad'?>"><?=$r['is_public']?'نعم':'لا'?></span></td><td><span class="pill <?=$used?'warn':'ok'?>"><?=$used?'نعم':'لا'?></span></td><td><form method="post" class="actions"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="toggle_public">Public</button><?php if(!$used):?><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف الملف؟')">حذف</button><?php endif;?></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php cmsAdminEnd();
